for kind,data in [('roots',R),('words',W)]: (OUT/f'{kind}_batch200_spec_02_bal.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
print('C0110',len(W),'new',sum(len(x['examples']) for x in W),'examples')
